Node.jsPythonGo <pre><code>import { SnerdQueue } from 'snerdmq-node';

const queue = new SnerdQueue();

queue.registerHandler('send_email', async (data) =&gt; {
    console.log(`Sending email to ${data.to}...`);
});

queue.enqueue({
    id: `email-${Date.now()}`,
    type: 'send_email',
    data: { to: 'user@example.com', subject: 'Hello' },
    maxRetries: 3,
    retryAfter: 0.5,
});
</code></pre> <pre><code>from snerdmq import SnerdQueue

queue = SnerdQueue()

async def send_email(data):
    print(f"Sending email to {data['to']}...")

queue.register_handler('send_email', send_email)

await queue.enqueue(
    task_id='email-123',
    task_type='send_email',
    data={'to': 'user@example.com', 'subject': 'Hello'},
    max_retries=3,
    retry_after_hours=0.5,
)
</code></pre> <pre><code>import snerdmq "github.com/speed-nerd/snerdmq-go"

queue, _ := snerdmq.NewSnerdQueue(snerdmq.SnerdQueueConfig{})
queue.RegisterHandler("send_email", func(ctx context.Context, data map[string]interface{}) error {
    fmt.Printf("Sending email to %v\n", data["to"])
    return nil
})
queue.Enqueue("email-123", "send_email", map[string]interface{}{"to": "user@example.com"}, 3, 0, "", 0, nil, nil, nil, nil, nil, nil)
</code></pre>

Node.jsPythonGoRubyPHPJavaC# / .NET <pre><code>// Enqueue with retry config
queue.enqueue({
    id: `email-${Date.now()}`,
    type: 'send_email',
    data: { to: 'user@example.com' },
    maxRetries: 3,
    retryAfter: 0.5,  // Wait 30 minutes before retrying
});

// Handle permanently failed tasks
queue.registerMaxRetryHandler('send_email', async (data) =&gt; {
    console.error(`Failed after all retries: ${JSON.stringify(data)}`);
    // Alert your team, update database, send Slack message...
});
</code></pre> <pre><code>await queue.enqueue(
